insert into special_fixture(k,doc,p) values('air-conditioner-cleaning',cms_shared_service_id('air-conditioner-cleaning'),'{"schemaVersion": 4, "publicTitle": "ניקוי מזגנים", "h1": "מזגן נקי יותר, אוויר נעים יותר", "seoTitle": "ניקוי מזגנים מקצועי עד הבית | CleanBrothers", "seoDescription": "ניקוי מזגנים מקצועי עד הבית באזור המרכז. שלחו תמונה בוואטסאפ, קבלו הערכת מחיר ותיאום מהיר עם CleanBrothers.", "copy": {"heroEyebrow": "ניקוי מזגנים מקצועי עד הבית", "heroDescription": "ניקוי מקצועי למזגנים עיליים בבית הלקוח, עם טיפול באבק, לכלוך וריחות לא נעימים בחלקים הנגישים לניקוי.", "heroCta": "שלחו תמונה וקבלו הערכת מחיר", "callCta": "התקשרו עכשיו", "imageCaption": "תמונות אמיתיות מהשטח", "signsEyebrow": "סימנים שכדאי לבדוק", "signsTitle": "מתי כדאי להזמין ניקוי מזגן?", "signsDescription": "הסימנים הבאים יכולים להעיד שהגיע הזמן לנקות הצטברות אבק ולכלוך. הם אינם אבחון של תקלה טכנית.", "cleaningEyebrow": "ניקוי יסודי ומסודר", "cleaningTitle": "מה כולל ניקוי מזגן?", "cleaningDescription": "מנקים את החלקים המרכזיים שנגישים לניקוי מקצועי, בלי להבטיח תיקון או שינוי בביצועי המזגן.", "cleaningNote": "היקף הניקוי בפועל נקבע לפי סוג המזגן, המבנה והנגישות לחלקים.", "technicalTitle": "ניקוי או תקלה טכנית?", "technicalDescription": "אנחנו מתמחים בניקוי עמוק של המזגן. אם לאחר הניקוי נשארת תקלה כמו אי־קירור, נזילה חריגה, רעשים או בעיית חשמל — ייתכן שיהיה צורך בטכנאי מזגנים מוסמך.", "processEyebrow": "תהליך פשוט וברור", "processTitle": "כך מזמינים ניקוי מזגן", "processDescription": "מתמונה ראשונה ועד ביקור מתואם בבית — בלי מנגנון פנייה חדש ובלי שלבים מיותרים.", "processCta": "שלחו תמונה עכשיו", "galleryEyebrow": "עבודות מהשטח", "galleryTitle": "עבודות ניקוי מזגנים אמיתיות", "galleryDescription": "תמונות מעבודות אמיתיות שבוצעו על ידי CleanBrothers. איננו מציגים זוג לפני ואחרי כאשר אין תיעוד מלא מאותה עבודה.", "pricingEyebrow": "הערכת מחיר לפי תמונה", "pricingTitle": "כמה עולה ניקוי מזגן?", "pricingDescription": "המחיר נקבע לפי סוג המזגן, מצב הלכלוך, הנגישות וכמות המזגנים. שלחו תמונה בוואטסאפ לקבלת הערכה מדויקת יותר.", "pricingCta": "קבלו הערכת מחיר", "multipleEyebrow": "תיאום מרוכז", "multipleTitle": "יש כמה מזגנים בבית?", "multipleDescription": "שלחו לנו תמונות של כל המזגנים ונוכל לתת הערכה מרוכזת ולתאם את כולם באותו ביקור, בהתאם לסוגי המזגנים ולגישה.", "multipleCta": "שלחו את כל התמונות", "areasEyebrow": "אזורי שירות", "areasTitle": "ניקוי מזגנים עד הבית באזור המרכז", "areasDescription": "מגיעים עם ציוד מקצועי לערי המרכז והשרון. שלחו תמונה ואת היישוב כדי לבדוק זמינות ולקבל הערכת מחיר.", "faqEyebrow": "שאלות נפוצות", "faqTitle": "מה חשוב לדעת לפני ניקוי מזגן?", "contactEyebrow": "הצעת מחיר לניקוי מזגן", "contactTitle": "שלחו תמונה או השאירו פרטים", "contactDescription": "ציינו את סוג המזגן, היישוב ומה תרצו לנקות. נחזור עם הערכה ותיאום לפי הזמינות באזורכם.", "contactCta": "שלחו תמונת מזגן וקבלו מחיר", "callPrefix": "התקשרו: ", "servicesCta": "לכל שירותי הניקוי של CleanBrothers"}, "trustItems": ["שירות עד הבית", "הערכת מחיר לפי תמונה", "זמינות מהירה באזור המרכז"], "airConditionerServiceAreas": ["ראשון לציון", "בת ים", "חולון", "תל אביב", "רמת גן", "גבעתיים", "גבעת שמואל", "פתח תקווה", "הוד השרון", "כפר סבא", "מרכז הארץ"], "intentSignals": ["ריח לא נעים בזמן ההפעלה", "אבק או לכלוך בפתחי האוויר", "מזגן שלא נוקה זמן רב", "לפני שימוש אינטנסיבי בקיץ", "לאחר תקופה ארוכה ללא שימוש"], "cleaningAreas": [{"title": "פילטרים", "description": "ניקוי יסודי מאבק ולכלוך שהצטברו עם הזמן."}, {"title": "סוללת המאייד", "description": "ניקוי הצטברויות באזור הסוללה, בהתאם לנגישות ולמצב המזגן."}, {"title": "תריסים ופתחי אוויר", "description": "ניקוי התריסים ופתחי יציאת האוויר מאבק ולכלוך."}, {"title": "תעלת ניקוז נגישה", "description": "ניקוי האזור הנגיש של מערכת הניקוז לפי מבנה המזגן."}, {"title": "מעטפת וחלקי פלסטיקה", "description": "ניקוי החלקים החיצוניים והפלסטיקה מאבק ולכלוך."}, {"title": "אזור המפוח הנגיש", "description": "ניקוי לכלוך שהצטבר באזור המפוח, כאשר המבנה והגישה מאפשרים זאת."}], "processSteps": ["שולחים תמונה בוואטסאפ", "מקבלים הערכת מחיר", "קובעים מועד", "מגיעים ומבצעים ניקוי מקצועי"], "faqs": [{"question": "מה כולל ניקוי מזגן?", "answer": "הניקוי מתמקד בפילטרים ובחלקים הנגישים ביחידה הפנימית, ובהם סוללת המאייד, תריסים, פתחי אוויר, מעטפת ואזורים נוספים שניתן להגיע אליהם בבטחה. ההיקף נקבע לפי סוג המזגן, המבנה והנגישות."}, {"question": "כמה זמן לוקח ניקוי מזגן?", "answer": "משך העבודה משתנה לפי סוג המזגן, הגישה אליו ורמת הלכלוך. לאחר קבלת תמונה ופרטים בסיסיים נוכל לתת הערכת זמן מדויקת יותר."}, {"question": "כל כמה זמן כדאי לנקות מזגן?", "answer": "התדירות תלויה בכמות השימוש, בסביבה ובהצטברות האבק. כדאי לפעול לפי הוראות היצרן ולשקול ניקוי מקצועי כשיש לכלוך נראה לעין, ריח לא נעים או לאחר תקופה ממושכת ללא ניקוי."}, {"question": "האם ניקוי יכול לעזור במקרה של ריח לא נעים?", "answer": "ניקוי עשוי לסייע כאשר מקור הריח הוא אבק או לכלוך בחלקים הנגישים. אם הריח נשאר לאחר הניקוי, ייתכן שמקורו בגורם אחר שדורש בדיקה של טכנאי מזגנים מוסמך."}, {"question": "האם אתם מתקנים מזגנים?", "answer": "לא. CleanBrothers מתמחים בניקוי מזגנים ולא בתיקון תקלות. אי־קירור, נזילה חריגה, רעשים או בעיית חשמל עשויים לדרוש טכנאי מזגנים מוסמך."}, {"question": "האם צריך להכין משהו לפני ההגעה?", "answer": "מומלץ לפנות חפצים מתחת למזגן ולאפשר גישה נוחה אליו. את שאר ההכנות וההגנה על אזור העבודה אנחנו מבצעים בהתאם למבנה ולגישה."}, {"question": "אפשר לנקות כמה מזגנים באותו ביקור?", "answer": "כן, בכפוף לסוגי המזגנים, הגישה והזמן הנדרש. שלחו תמונות של כל היחידות כדי שנוכל לתת הערכה מרוכזת ולתאם את הביקור."}, {"question": "האם אתם מנקים מזגן עילי בלבד או גם סוגים אחרים?", "answer": "השירות המרכזי הוא למזגנים עיליים. אפשר לשלוח תמונה של מזגן מסוג אחר ונבדוק אם המבנה והגישה מתאימים לשירות הניקוי שאנחנו מציעים."}], "serviceDescription": "ניקוי מזגנים מקצועי בבית הלקוח, עם טיפול באבק ובלכלוך בחלקים הנגישים לניקוי.", "keywords": ["ניקוי מזגנים", "ניקוי מזגן", "ניקוי מזגן עילי", "ניקוי מזגנים בבית", "ניקוי מזגן מריח רע", "ניקוי מזגנים במרכז", "ניקוי מזגנים מקצועי"], "media": {"hero": [{"versionId": "b920443f-55c5-4b27-a232-154b3688320e", "alt": "עבודות ניקוי מזגנים אמיתיות של CleanBrothers"}, {"versionId": "ba7745a4-fe0c-44fb-913c-971aaef4f486", "alt": "עבודות ניקוי מזגנים אמיתיות של CleanBrothers"}, {"versionId": "9c3e4c0f-d64b-47c7-9fb4-8f643af949a2", "alt": "עבודות ניקוי מזגנים אמיתיות של CleanBrothers"}], "gallery": [{"versionId": "ba7745a4-fe0c-44fb-913c-971aaef4f486", "alt": "עבודת ניקוי מזגן אמיתית של CleanBrothers, תמונה 1"}, {"versionId": "9c3e4c0f-d64b-47c7-9fb4-8f643af949a2", "alt": "עבודת ניקוי מזגן אמיתית של CleanBrothers, תמונה 2"}, {"versionId": "b920443f-55c5-4b27-a232-154b3688320e", "alt": "עבודת ניקוי מזגן אמיתית של CleanBrothers, תמונה 3"}], "seo": [{"versionId": "b920443f-55c5-4b27-a232-154b3688320e", "alt": "ניקוי מזגן מקצועי של CleanBrothers בבית הלקוח"}]}, "promotion": {"enabled": true, "startingPrice": 199, "regularPrice": 250, "bundleEnabled": true, "badge": "מבצע קיץ ☀️", "heroLabel": "מבצע קיץ", "pricePrefix": "ניקוי מזגן החל מ־", "description": "שלחו לנו תמונות של המזגנים בוואטסאפ וקבלו הצעת מחיר מדויקת.", "cta": "שלחו תמונות וקבלו מחיר", "priceTerms": "המחיר הסופי נקבע לפי סוג המזגן, מצבו, הנגישות ומיקום השירות.", "bundleTerms": "מבצע המזגן השישי מתייחס לניקוי במסגרת אותו ביקור ובאותה כתובת, בכפוף להתאמת המזגנים לשירות."}}'::jsonb);
insert into special_fixture(k,doc,p) values('window-cleaning',cms_shared_service_id('window-cleaning'),'{"schemaVersion": 5, "publicTitle": "ניקוי חלונות", "h1": "ניקוי חלונות מקצועי לבית ולעסק", "seoTitle": "ניקוי חלונות מקצועי לבית ולעסק | CleanBrothers", "seoDescription": "ניקוי חלונות בדירות, בתים ומשרדים, כולל זכוכית, מסגרות, מסילות, תריסים ורשתות בחלונות בעלי גישה בטוחה. לקבלת הערכת מחיר מ-CleanBrothers.", "copy": {"heroEyebrow": "ניקוי חלונות בבית הלקוח", "heroDescription": "ניקוי זכוכית, מסגרות, מסילות, תריסים ורשתות בדירות, בתים ומשרדים — בהתאם למצב החלונות ולגישה בטוחה.", "heroCta": "שלחו תמונות ב-WhatsApp", "includedEyebrow": "מה כולל השירות", "includedTitle": "ניקוי שמתייחס לכל חלקי החלון", "includedDescription": "היקף העבודה נקבע לפי סוג החלונות, מצבם והגישה אליהם. לפני התיאום בודקים תמונות ומסבירים מה ניתן לכלול.", "propertyEyebrow": "סוגי נכסים", "propertyTitle": "לדירות, בתים ומשרדים", "processEyebrow": "תהליך העבודה", "processTitle": "מתמונה ראשונית ועד ניקוי מסודר", "audienceEyebrow": "למי השירות מתאים", "audienceTitle": "למי שמחפש ניקוי יסודי בחלונות נגישים", "audienceDescription": "השירות מתאים לדיירים, בעלי בתים ומשרדים שרוצים לנקות את הזכוכית ואת חלקי החלון הנלווים, כולל לאחר שיפוץ, כאשר קיימת גישה בטוחה לעבודה.", "safetyEyebrow": "חשוב לדעת מראש", "safetyTitle": "עבודה בטוחה ותיאום ציפיות ברור", "safetyDescription": "השירות מיועד לחלונות בעלי גישה בטוחה ואינו כולל עבודות בגובה או סנפלינג. התוצאה תלויה בסוג הזכוכית, מצבה, סוג הלכלוך ונגישות החלון.", "faqEyebrow": "שאלות נפוצות", "faqTitle": "מה חשוב לדעת לפני שמזמינים ניקוי חלונות?", "contactEyebrow": "הצעת מחיר לניקוי חלונות", "contactTitle": "שלחו תמונות או השאירו פרטים", "contactDescription": "כדי להעריך את העבודה, כדאי לצלם את החלונות, המסגרות והגישה אליהם ולציין את סוג הנכס והעיר.", "callPrefix": "התקשרו: ", "callCta": "התקשרו עכשיו", "quoteCta": "קבלת הצעת מחיר"}, "includedItems": ["ניקוי משטחי זכוכית", "ניקוי מסגרות", "ניקוי מסילות", "ניקוי תריסים", "ניקוי רשתות"], "propertyTypes": [{"title": "דירות ובתים", "text": "חלונות בחדרים, בסלון ובאזורים נוספים שניתן להגיע אליהם בבטחה."}, {"title": "משרדים", "text": "ניקוי חלונות פנימיים וחיצוניים במשרדים עם גישה בטוחה ונוחה."}, {"title": "לאחר שיפוץ", "text": "טיפול באבק ובשאריות שניתן להסיר בהתאם לסוג הזכוכית, מצבה וסוג הלכלוך."}], "process": ["שולחים תמונות של החלונות והגישה אליהם", "בודקים את סוג החלון, היקף העבודה והמגבלות", "מתאמים ציפיות והערכת מחיר לפני ההגעה", "מבצעים ניקוי מסודר ובודקים את התוצאה"], "faqs": [{"question": "האם השירות כולל ניקוי מסילות, תריסים ורשתות?", "answer": "אפשר לכלול מסגרות, מסילות, תריסים ורשתות בהתאם לסוג החלון, למצבם ולגישה. מומלץ לשלוח תמונות כדי שנוכל להעריך את היקף העבודה."}, {"question": "האם אתם מנקים חלונות לאחר שיפוץ?", "answer": "כן, כאשר קיימת גישה בטוחה. היכולת להסיר שאריות תלויה בסוג הזכוכית, במצבה ובסוג הלכלוך, ולכן בודקים תמונות ומתאמים ציפיות מראש."}, {"question": "האם אתם מבצעים עבודות בגובה או סנפלינג?", "answer": "לא. השירות מיועד לחלונות בעלי גישה בטוחה ואינו כולל עבודות בגובה או סנפלינג."}, {"question": "איך מקבלים הערכת מחיר?", "answer": "שולחים ב-WhatsApp תמונות של החלונות, המסגרות והגישה אליהם, יחד עם סוג הנכס והעיר. כך ניתן להעריך את היקף העבודה בצורה מדויקת יותר."}, {"question": "האם כל כתם או שארית צבע ניתנים להסרה?", "answer": "לא תמיד. התוצאה תלויה בסוג הזכוכית, במצבה, בסוג הלכלוך ובנגישות החלון. לפני העבודה נסביר מה ניתן לבצע בלי להבטיח הסרה שאינה ודאית."}], "media": {"hero": []}}'::jsonb);
